package packages_2;

public class Task_7_7_7 {
	// Multiplication table of n using do-while loop
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int table = 4, upto = 15, i = 1;
		do {
			System.out.println(table + "*" + i + "=" + table * i);
			i++;
		} while (i <= upto);
	}

}
